  "status": "SUPPORTED",
  "claim": {
    "component_id": "C022",
    "value": "A single fast export is insufficient grounds for discarding revision history.",
    "scope": "Evidence limitation on elimination decisions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly prohibits discarding history based on a single fast export."
    }
  },
  "signal_basis": {
    "component_id": "C022_SIGNAL",
    "value": "One export is fast, but revision classification requires evidence about the fraction exceeding one hour and its uncertainty; absence of a slow export in a small sample cannot establish goodness.",
    "scope": "Classification of a revision against the defined tail-rate ranges before eliminating history.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
