          "role": "SUPPORT"
        },
        {
          "source_id": "P002",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle supplies the single-fast-export observation, the required tail-rate evidence, and the explicit small-sample limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without establishing an additional empirical relation."
    }
  },
  "rationale": "A fast export is compatible with both acceptable and elevated rates of rare delays. That observation alone cannot classify the revision confidently and therefore cannot justify eliminating revision history.",
  "uncertainty": "The observation leaves the revision's tail-rate classification unresolved; this supports the stated evidence limitation.",
  "anomalies": []
}
